function money(n){return new Intl.NumberFormat("es-VE",{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n||0));}
function nfmt(n,d=2){return new Intl.NumberFormat("es-VE",{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n||0));}
function yearsSince(date){const d=new Date(date+"T12:00:00");let y=HOY.getFullYear()-d.getFullYear();const m=HOY.getMonth()-d.getMonth();if(m<0||(m===0&&HOY.getDate()<d.getDate())) y--;return Math.max(0,y);}
function age(date){const d=new Date(date+"T12:00:00");let y=HOY.getFullYear()-d.getFullYear();const m=HOY.getMonth()-d.getMonth();if(m<0||(m===0&&HOY.getDate()<d.getDate())) y--;return y;}
function pct(n){return `${(n*100).toFixed(n*100%1?1:0)}%`;}
function serviceFractionYears(date){const d=new Date(date+"T12:00:00");let years=HOY.getFullYear()-d.getFullYear();let ann=new Date(d);ann.setFullYear(d.getFullYear()+years);if(ann>HOY){years--;ann.setFullYear(ann.getFullYear()-1)}const months=(HOY.getFullYear()-ann.getFullYear())*12+(HOY.getMonth()-ann.getMonth())-(HOY.getDate()<ann.getDate()?1:0);return years+(months>6?1:0);}

function calc(e){
  const years=yearsSince(e.ingreso);
  const normal=e.salarioBase+e.primaProfesional+e.primaHijo;
  const daily=normal/30;
  const vacDias=Math.min(15+Math.max(0,years-1),30);
  const bonoVacDias=Math.min(15+years,30);
  const aliqVac=(daily*bonoVacDias)/360;
  const aliqUtil=(daily*PARAMS.utilidadesDias)/360;
  const integralDaily=daily+aliqVac+aliqUtil;
  const integralMonth=integralDaily*30;
  const hora=daily/8;
  const extra=e.horasExtra*hora*(1+PARAMS.extra);
  const noct=e.nocturnas*hora*PARAMS.nocturno;
  const fer=e.feriados*daily*(1+PARAMS.feriado);
  const gross=normal+extra+noct+fer;
  const ivssMonthlyBase=Math.min(normal,5*SM_REF);
  const ivssWeekly=ivssMonthlyBase*12/52;
  const ivssTrab=ivssWeekly*PARAMS.ivssTrab*SEMANAS_IVSS;
  const ivssPat=ivssWeekly*PARAMS.ivssPatronoDemo*SEMANAS_IVSS;
  const rpeBase=Math.min(Math.max(normal,SM_REF),10*SM_REF);
  const rpeTrab=rpeBase*PARAMS.rpeTrab, rpePat=rpeBase*PARAMS.rpePat;
  const faovTrab=integralMonth*PARAMS.faovTrab, faovPat=integralMonth*PARAMS.faovPat;
  const caja=normal*e.cajaPct;
  const loanMax=normal*PARAMS.loanLimit;
  const loan=Math.min(e.loanCuota,e.loanBalance,loanMax);
  const deductions=ivssTrab+rpeTrab+faovTrab+caja+e.sintel+loan;
  const net=gross-deductions;
  const patronContrib=ivssPat+rpePat+faovPat;
  const quarter=integralDaily*15;
  const interestMonth=e.prestCapital*e.tasaInteres/12;
  const advanceMax=e.prestCapital*PARAMS.anticipoPrest;
  const vacPay=vacDias*daily;
  const vacBonus=bonoVacDias*daily;
  const utilMin=PARAMS.utilidadesDias*daily;
  return {years,normal,daily,vacDias,bonoVacDias,aliqVac,aliqUtil,integralDaily,integralMonth,hora,extra,noct,fer,gross,ivssMonthlyBase,ivssWeekly,ivssTrab,ivssPat,rpeBase,rpeTrab,rpePat,faovTrab,faovPat,caja,loanMax,loan,deductions,net,patronContrib,quarter,interestMonth,advanceMax,vacPay,vacBonus,utilMin};
}

